body:
Hi there! I literally got hit with the same issue a couple of hours ago. I don't have a solution (and would love to get help finding a workaround, too!) but I have a couple of observations to help us move forward:

1. In my version of the stripped down project, I don't get the `OS::get_process_id()`, so it's not the blocker.
2. The link after `The AudioContext was not allowed to start. ` error suggests it's related to browsers forbidding autoplay without user interaction first. I think that fundamentally, autoplay shouldn't be needed for recording (initially I tried to do recording separately from Godot in javascript and I wasn't getting the error there, but sending the data to godot was annoying/difficult/impossible), but in the example demo project, it's necessary for AudioStreamRecorder to record anything.

I have managed to resolve this, by having this html shell:
```html
<html>
    <head>
        <title>My Template</title>
        <meta charset="UTF-8">
    </head>
    <body>
        <script>
        var audioContext = null;
        function resumeAudioContext() {
            if (audioContext == null) {
                audioContext = new AudioContext();
                var engine = new Engine($GODOT_CONFIG);
                engine.startGame();
            }
            if (audioContext.state !== 'running') {
                audioContext.resume();
                var engine = new Engine($GODOT_CONFIG);
                engine.startGame();
            }
        }
        </script>
        <canvas id="canvas"></canvas>
        <script src="$GODOT_URL"></script>
        <script>
      var button = document.createElement('button');
			button.innerHTML = 'Click to enable audio';
			button.onclick = function() {
				resumeAudioContext();
				button.remove();
			};
			document.body.appendChild(button);
        </script>
    </body>
</html>
```
It's not great, but it makes the warning to go away. However, I'm still getting the `current_instance->recording_data.is_empty`.

Fwiw, I am getting this on Ubuntu + Godot 4.3.

1. I tested your project under that link but I was only able to play back the audio from the bus, not he microphone.
2. However, I tested your code and I was able to record microphone as well, here's my modified code:
```
func _ready():
	var idx = AudioServer.get_bus_index("record")
	effect = AudioServer.get_bus_effect(idx, 0)
	capture_mix_rate = AudioServer.get_mix_rate()


func _process(delta: float) -> void:
	if is_recording:
		var available_frames = effect.get_frames_available()
		if available_frames > 0:
			var buffer = effect.get_buffer(available_frames)  # Get only the required frames
			for frame in buffer:
				data.append(frame.x)  # Left channel

func convert_to_wav(audio_data: PackedFloat32Array) -> AudioStreamWAV:
	var wav_stream = AudioStreamWAV.new()

	# Convert from float (-1.0 to 1.0) to 16-bit PCM (-32768 to 32767)
	var pcm_data = PackedByteArray()
	for i in range(0, audio_data.size()):  # Process stereo pairs
		var left_sample = int(clamp(audio_data[i] * 32767.0, -32768, 32767))

		# Append left sample (little-endian format)
		pcm_data.append(left_sample & 0xFF)
		pcm_data.append((left_sample >> 8) & 0xFF)

	wav_stream.format = AudioStreamWAV.FORMAT_16_BITS
	wav_stream.mix_rate = capture_mix_rate
	print("mix rate = %s" % capture_mix_rate)
	wav_stream.stereo = false  # Enable stereo playback
	wav_stream.data = pcm_data  # Convert to byte array

	return wav_stream

func _on_record_pressed() -> void:
	if not is_recording:
		effect.clear_buffer()
		data.clear()
		$AudioStreamRecorder.autoplay = true
		$play.disabled = true
		$record.text = "Stop"
		$status.text = "Recording..."
	else:
		print("Playing captured audio")
		var capture_wav = convert_to_wav(data)
		print("capture_wav.format: %s" % capture_wav.format)
		print("capture_wav.mix_rate: %s" % capture_wav.mix_rate)
		print("capture_wav.stereo: %s" % capture_wav.stereo)
		var _data = capture_wav.get_data()
		print("data.size(): %s" % _data.size())
		$AudioStreamPlayer.stream = capture_wav
		$play.disabled = false
		$record.text = "Record"
		$status.text = ""

	is_recording = not is_recording


func _on_play_pressed() -> void:
	$AudioStreamPlayer.play()
```
I think the only meaningful difference I made was to make sure the stream player is autoplayed
I uploaded it here: http://sygi.itch.io/test-recording?secret=PHXwpIBc8mAeffpLBxbn932JY
